mapper.select:
SELECT FROM teacher t LEFT JOIN sys_user u ON t.user_id = u.id LEFT JOIN department d ON t.department_id = d.id WHERE 1=1
AND t.teacher_no LIKE CONCAT('%', #{teacherNo}, '%')
AND t.real_name LIKE CONCAT('%', #{realName}, '%')
AND t.department_id = #{departmentId}
ORDER BY t.create_time DESC LIMIT #{offset}, #{limit}

mapper.update:
UPDATE teacher
teacher_no = #{teacherNo}, real_name = #{realName}, gender = #{gender}, phone = #{phone}, email = #{email}, department_id = #{departmentId}, user_id = #{userId},
WHERE id = #{id}

mapper.select:
SELECT COUNT(*) FROM teacher 
WHERE YEAR(create_time) = #{year} 
AND MONTH(create_time) = #{month}

SELECT COUNT(DISTINCT class_id) 
FROM teacher_class 
WHERE teacher_id = #{teacherId}
